<?php
namespace App\Http\Controllers;
use App\Models\PropertyClient; use Illuminate\Http\Request; use Illuminate\Support\Str;
class ClientController extends Controller { public function index(){ abort_unless(auth()->user()->canAccessModule('properties'),403); $clients=PropertyClient::withCount('properties')->orderBy('name')->paginate(15); return view('clients.index',compact('clients')); } public function store(Request $request){ abort_unless(in_array(auth()->user()->role,['Owner','Super Admin'],true),403); $data=$request->validate(['name'=>['required','string','max:255'],'phone'=>['required','string','max:30'],'email'=>['nullable','email'],'address'=>['nullable','string','max:1000']]); PropertyClient::create($data+['organization_id'=>auth()->user()->organization_id,'portal_token'=>Str::random(48)]); return back()->with('success','Client added.'); } public function portal(string $token){ $client=PropertyClient::withoutGlobalScopes()->where('portal_token',$token)->with(['properties'=>fn($query)=>$query->withCount(['units','units as occupied_units_count'=>fn($units)=>$units->where('status','Occupied')])->withSum('units','monthly_rent')->orderBy('name')])->firstOrFail(); return view('client-portal.show',compact('client')); } }
